// ───────────────────────────── FAQs ─────────────────────────────

export const FAQS: { category: string; question: string; answer: string; serviceSlugs?: string[] }[] = [
  { category: "Pricing", question: "How is pricing calculated?", answer: "Every project gets a fixed-scope quote based on what you need: number and length of videos, complexity, deliverables and turnaround. You can also choose per-video or per-short pricing, or a monthly retainer for ongoing work. You'll see the full itemised price before anything starts." },
  { category: "Pricing", question: "Do you offer monthly plans?", answer: "Yes. Retainers include a set number of videos or shorts each month with a predictable price, priority scheduling and usage tracking in your portal. Ask about a retainer when you start a project or book a call." },
  { category: "Pricing", question: "Is there a deposit?", answer: "Projects are usually started with a deposit (shown in your quote) and the balance is invoiced when you approve the final version. Your quote states the exact split." },
  { category: "Turnaround", question: "How long does editing take?", answer: "Turnaround depends on the service and length — it's shown on each service page and confirmed in your quote. The clock starts when your project brief is complete and all required files are uploaded. Rush delivery may be available for an additional fee." },
  { category: "Turnaround", question: "What happens if I'm late sending files or feedback?", answer: "The timeline moves with you. We'll always show the expected draft date in your project and remind you if we're waiting on something." },
  { category: "Revisions", question: "How many revisions are included?", answer: "Your quote and contract state the included revision rounds — our standard is two. A round is one consolidated set of notes on a draft. You leave timestamped comments on the video and send them as a single revision request." },
  { category: "Revisions", question: "What if I want changes after approving?", answer: "Approval confirms the version meets the agreed requirements. After that, further changes are treated as a new request or a change order, which we'll quote separately." },
  { category: "Revisions", question: "What counts as a scope change?", answer: "Changing the agreed deliverables, adding new footage or formats, or altering the direction after production started is a scope change. Submit a change request in your project and we'll classify it as included, out of scope, or quote the extra cost." },
  { category: "Files", question: "How do I send my footage?", answer: "Upload directly from your project's Files tab — drag and drop with a progress bar, into folders like Raw Footage, Audio, Brand Assets and Music. Large files are sent straight to secure cloud storage." },
  { category: "Files", question: "What files should I send?", answer: "Raw footage or recordings, clean audio if recorded separately, your logo (PNG/SVG), brand colours and fonts, scripts or talking points, reference videos, and any music you want used. Your project setup form tells you exactly what's needed for your type of video." },
  { category: "Files", question: "Is my footage private?", answer: "Yes. Files are stored in access-controlled cloud storage and served through short-lived signed links. Only you, your team members and the studio staff assigned to your project can access them." },
  { category: "Files", question: "How long do you keep my files?", answer: "We keep your project files so repeat projects are fast. You can ask us to delete any project's files at any time." },
  { category: "Payments", question: "How does payment work?", answer: "After you accept a quote and sign the agreement, you'll receive an invoice in your portal. Payment activates your project. Any remaining balance is invoiced when you approve the final version." },
  { category: "Payments", question: "Which currencies and payment methods do you support?", answer: "Quotes and invoices can be issued in multiple currencies. Available payment methods depend on the studio's payment provider and are shown at checkout." },
  { category: "Editing", question: "Can you match my existing style?", answer: "Yes. Save your brand kit — logos, colours, fonts and music preferences — and share reference videos. We keep your style consistent across projects." },
  { category: "Editing", question: "Who edits my videos?", answer: "A named editor is assigned to your project and you can message them (or the project manager) right inside the project. Repeat clients keep the same editor where possible." },
  { category: "Editing", question: "Do you provide the project files?", answer: "Final videos, captions and requested formats are always delivered. Editable source files can be included if agreed in your quote." },
  { category: "Retainers", question: "How do retainer allowances work?", answer: "Your retainer includes a set number of videos, shorts or hours each month. Your dashboard shows what you've used, what's left, upcoming projects and your renewal date." },
  { category: "Retainers", question: "Can I pause or cancel a retainer?", answer: "Yes — retainers can be paused or cancelled according to your agreement. Contact us or message your project manager." },
  { category: "Contracts", question: "Do I need to sign a contract?", answer: "Yes. Each project has a short agreement covering scope, deliverables, turnaround, payment terms, revision limits, usage rights, confidentiality and cancellation. You can read, download and e-sign it from your portal." },
  { category: "Contracts", question: "Who owns the final videos?", answer: "You do. On full payment you receive a licence to use the final deliverables for your business purposes, as described in your agreement." },
  { category: "Editing", question: "Can you edit podcasts with multiple cameras?", answer: "Yes — we sync and switch multicam footage, clean the audio and produce the full episode, a YouTube version and social clips.", serviceSlugs: ["podcast-editing"] },
  { category: "Editing", question: "What formats do you deliver short-form in?", answer: "9:16 vertical by default, plus 1:1 and 4:5 on request, with captions burned in or delivered as a caption file.", serviceSlugs: ["short-form-video-editing", "ugc-editing", "social-media-clips"] },
  { category: "Editing", question: "Can you make MLS-compliant listing videos?", answer: "Yes. Tell us your MLS requirements and we'll deliver an unbranded, compliant version alongside your branded social edits.", serviceSlugs: ["real-estate-video-editing"] },
];

