// ───────────────────────────── default automations ─────────────────────────────

export interface AutoSeed {
  name: string;
  description: string;
  event: string;
  conditions?: unknown;
  actions: { type: "EMAIL" | "NOTIFICATION" | "STATUS_UPDATE" | "CREATE_TASK" | "ADMIN_ALERT" | "CLIENT_REMINDER"; config: Record<string, unknown>; delayMinutes?: number }[];
}

const N = (recipient: string, title: string, message: string, link: string, category = "PROJECT", extra: Record<string, unknown> = {}) => ({ type: "NOTIFICATION" as const, config: { recipient, title, message, link, category, ...extra } });
const E = (recipient: string, templateKey: string, category = "PROJECT", extra: Record<string, unknown> = {}) => ({ type: "EMAIL" as const, config: { recipient, templateKey, category, ...extra } });

